Slack.State state = new Slack.State();
Slack.TestHarness.Enterprise enterprise = state.createEnterprise('E1', 'Example');
System.assertNotEquals(null, state.createEnterprise('Solo'));
Slack.TestHarness.Team team = state.createTeam('example', enterprise);
System.assertNotEquals(null, state.createTeam('solo'));
Slack.TestHarness.User user = state.createUser('muser', 'M User', team, 'en_US');
System.assertNotEquals(null, state.createUser('two', 'Two User'));
System.assertNotEquals(null, state.createUser('three', 'Three User', team));
Slack.TestHarness.Channel publicChannel = state.createPublicChannel(team, 'general', 'en_US');
System.assertNotEquals(null, state.createPublicChannel(team, 'ops'));
System.assertNotEquals(null, state.createPublicChannel('default-public'));
System.assertNotEquals(null, state.createPrivateChannel(team, 'private', 'en_US'));
System.assertNotEquals(null, state.createPrivateChannel(team, 'private-two'));
System.assertNotEquals(null, state.createPrivateChannel('default-private'));
System.assertNotEquals(null, state.createDirectChannel(user));
Slack.TestHarness.UserSession defaultSession = state.createUserSession();
System.assertNotEquals(null, defaultSession);
Slack.TestHarness.UserSession session = state.createUserSession(user, publicChannel);
System.assertNotEquals(null, session.getState());
System.assertNotEquals(null, session.getUser());
System.assertNotEquals(null, session.getOpenChannel());
System.assertEquals(0, session.getMessageCount());
System.assertEquals(0, session.getMessages().size());
System.assertEquals(0, session.getModalStack().size());
System.assertEquals(null, session.getTopModal());
Slack.App app = new Slack.App();
System.assertNotEquals(null, session.openAppHome(app));
System.assertNotEquals(null, session.getAppHome());
System.assertNotEquals(null, session.openChannel('C123'));
Slack.TestHarness.Message message = session.postMessage('hello');
System.assertNotEquals(null, message);
System.assertEquals(1, session.getMessageCount());
System.assertEquals(1, session.getMessages().size());
session.executeEvent(new Slack.Event(), app);
session.executeGlobalShortcut('global', app);
session.executeMessageShortcut('message', message, app);
session.executeSlashCommand('/local', app);
session.executeSlashCommand('/local', 'text', app);
session.closeModal();
session.closeAllModals();
state.clearAppClientMock();
state.clearBotClientMock();
state.clearUserClientMock();
state.clearAllClientMocks();
System.assertEquals(false, new Slack.EventDispatcher().allowUnauthenticatedUsers());
System.assertEquals(false, new Slack.ShortcutDispatcher().allowUnauthenticatedUsers());
System.assertEquals(false, new Slack.SlashCommandDispatcher().allowUnauthenticatedUsers());
Slack.TestHarness.Option option = new Slack.TestHarness.Option();
Slack.CheckboxGroup groupValue = new Slack.CheckboxGroup();
groupValue.toggleValue(option);
Slack.Overflow overflow = new Slack.Overflow();
overflow.clickOption(0);
overflow.clickOption(option);

